nent-export="default" renderer-url="/_astro/client.8CyCEayk.js" props="{&quot;featuredImage&quot;:[0,&quot;https://media.fittour.vn/uploads/du-lich-alaska-usa-phan-2-thuong-vu-72-trieu-usd-thay-doi-lich-su-nuoc-my.webp&quot;],&quot;config&quot;:[0,{&quot;seriesTitle&quot;:[0,&quot;ALASKA&quot;],&quot;heroSubtitle&quot;:[0,&quot;Vì Sao Nga Bán Alaska Cho Mỹ Chỉ Với 7,2 Triệu USD?&quot;],&quot;heroChapter&quot;:[0,&quot;PHẦN II • THƯƠNG VỤ LỊCH SỬ&quot;],&quot;heroQuote&quot;:[0,&quot;\&quot;Có những quyết định mà chỉ nhiều thập kỷ sau người ta mới nhận ra tầm nhìn thực sự của nó. Câu chuyện Alaska là một ví dụ điển hình.\&quot;&quot;],&quot;sections&quot;:[1,[[0,{&quot;id&quot;:[0,&quot;intro&quot;],&quot;order&quot;:[0,1],&quot;title&quot;:[0,&quot;Những Quyết Định Bị Xem Là Sai Lầm&quot;],&quot;subtitle&quot;:[0,&quot;A Historical Misjudgment&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Trong lịch sử thế giới, có những quyết định bị xem là sai lầm ngay từ ngày đầu tiên.&quot;],[0,&quot;Có những thương vụ khiến báo chí chế giễu, công chúng phản đối và giới quan sát không nhìn thấy bất kỳ giá trị nào phía trước.&quot;],[0,&quot;Nhưng cũng có những quyết định mà chỉ nhiều thập kỷ sau người ta mới nhận ra tầm nhìn thực sự của nó.&quot;],[0,&quot;Câu chuyện Alaska là một ví dụ điển hình.&quot;],[0,&quot;Ngày nay, khi nhắc đến Alaska, người ta nghĩ đến những dãy núi phủ tuyết trắng, những dòng sông băng xanh thẳm, những đàn cá voi di cư mỗi mùa hè và nguồn tài nguyên thiên nhiên khổng lồ. Thế nhưng cách đây hơn 150 năm, vùng đất rộng hơn 1,7 triệu km² này từng được bán với giá chỉ 7,2 triệu USD.&quot;],[0,&quot;Một con số khiến rất nhiều người ngày nay phải ngạc nhiên.&quot;],[0,&quot;Liệu đây có phải là một trong những thương vụ rẻ nhất trong lịch sử nhân loại?&quot;]]],&quot;keyInsight&quot;:[0,&quot;Có những quyết định mang tính lịch sử mà phải qua hàng trăm năm con người mới thực sự thấu hiểu tầm nhìn vĩ đại đằng sau nó.&quot;],&quot;highlightText&quot;:[0,&quot;Một vùng đất trị giá hàng nghìn tỷ đô ngày nay từng được bán với giá chỉ 7,2 triệu USD.&quot;]}],[0,{&quot;id&quot;:[0,&quot;russian-alaska&quot;],&quot;order&quot;:[0,2],&quot;title&quot;:[0,&quot;Khi Nga Sở Hữu Một Phần Bắc Mỹ&quot;],&quot;subtitle&quot;:[0,&quot;Russian America&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Trước khi trở thành tiểu bang lớn nhất nước Mỹ, Alaska từng là lãnh thổ của Đế quốc Nga.&quot;],[0,&quot;Vào thế kỷ 18, các nhà thám hiểm Nga vượt qua eo biển Bering và tiến vào vùng đất rộng lớn nằm giữa Bắc Băng Dương và Thái Bình Dương. Tại đây, họ phát hiện nguồn tài nguyên vô cùng giá trị vào thời điểm đó: lông thú.&quot;],[0,&quot;Rái cá biển, cáo Bắc Cực và hải cẩu trở thành những mặt hàng xa xỉ được săn đón tại châu Âu và châu Á. Các thương nhân Nga nhanh chóng thiết lập mạng lưới giao thương dọc theo bờ biển Alaska.&quot;],[0,&quot;Trong nhiều thập kỷ, Alaska đóng vai trò như một tiền đồn xa xôi của Đế quốc Nga tại Bắc Mỹ.&quot;],[0,&quot;Tuy nhiên, khoảng cách địa lý quá lớn khiến việc quản lý trở nên vô cùng khó khăn. Từ Saint Petersburg đến Alaska là hành trình kéo dài hàng tháng trời. Chi phí vận hành ngày càng tăng trong khi ngành buôn bán lông thú dần suy giảm.&quot;],[0,&quot;Sau thất bại trong Chiến tranh Crimea, nền kinh tế Nga chịu nhiều áp lực. Chính phủ Nga bắt đầu cân nhắc một quyết định mà ít ai ngờ tới: bán Alaska.&quot;],[0,&quot;Đối với nhiều người Nga thời điểm đó, Alaska không phải một kho báu.&quot;],[0,&quot;Đó là một vùng đất xa xôi, lạnh giá và khó bảo vệ.&quot;],[0,&quot;Điều thú vị là dấu ấn của thời kỳ Nga vẫn còn hiện diện tại Alaska ngày nay. Những du khách ghé thăm Sitka – thủ phủ cũ của Alaska thuộc Nga – vẫn có thể nhìn thấy các nhà thờ Chính thống giáo với mái vòm đặc trưng. Giữa khung cảnh rừng thông, núi tuyết và đại dương phương Bắc, những công trình này tạo nên cảm giác như đang đứng giữa giao điểm của hai thế giới.&quot;],[0,&quot;Chính sự pha trộn giữa văn hóa bản địa Alaska, di sản Nga và nước Mỹ hiện đại đã góp phần tạo nên bản sắc rất riêng cho vùng đất này.&quot;]]],&quot;keyInsight&quot;:[0,&quot;Sự sụp đổ của một đế chế đôi khi lại mở ra cánh cửa cho một quốc gia khác trỗi dậy mạnh mẽ hơn bao giờ hết.&quot;],&quot;highlightText&quot;:[0,&quot;Sự pha trộn giữa văn hóa bản địa, di sản Nga và Mỹ hiện đại đã tạo nên bản sắc rất riêng.&quot;]}],[0,{&quot;id&quot;:[0,&quot;sewards-folly&quot;],&quot;order&quot;:[0,3],&quot;title&quot;:[0,&quot;\&quot;Sự Điên Rồ Của Seward\&quot;&quot;],&quot;subtitle&quot;:[0,&quot;Seward''s Folly&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Năm 1867, Ngoại trưởng Mỹ William H. Seward hoàn tất thỏa thuận mua Alaska từ Nga với giá 7,2 triệu USD.&quot;],[0,&quot;Nếu chia theo diện tích, nước Mỹ chỉ phải trả khoảng hai xu cho mỗi acre đất.&quot;],[0,&quot;Ngày nay, mức giá ấy nghe gần như không thể tin nổi.&quot;],[0,&quot;Nhưng vào thời điểm đó, phản ứng của công chúng Mỹ lại hoàn toàn khác. Báo chí đồng loạt chỉ trích thương vụ này.&quot;],[0,&quot;Một số tờ báo gọi Alaska là \&quot;Chiếc hộp băng của Seward\&quot;.&quot;],[0,&quot;Những người khác chế giễu đây là \&quot;Vườn gấu Bắc Cực của Tổng thống\&quot;.&quot;],[0,&quot;Trong mắt phần lớn người dân Mỹ lúc bấy giờ, Alaska chỉ là một vùng đất phủ đầy tuyết, gấu hoang và những cơn bão lạnh giá.&quot;],[0,&quot;Không ai nhìn thấy tương lai. Không ai nghĩ rằng vùng đất này sẽ thay đổi lịch sử nước Mỹ.&quot;],[0,&quot;Điều thú vị là những quyết định mang tính bước ngoặt thường có một điểm chung. Khi cơ hội còn nằm dưới lớp băng, rất ít người nhận ra giá trị thật của nó.&quot;],[0,&quot;Có một câu hỏi mà nhiều du khách ngày nay thường đặt ra khi tìm hiểu về Alaska: Alaska có giống phần còn lại của nước Mỹ hay không?&quot;],[0,&quot;Câu trả lời là không hẳn. Trong khi phần lớn nước Mỹ gắn liền với những đô thị hiện đại và mạng lưới giao thông dày đặc, Alaska vẫn giữ cảm giác của một vùng đất biên cương.&quot;],[0,&quot;Nhiều cộng đồng nằm cách biệt hàng trăm kilomet. Một số ngôi làng chỉ có thể tiếp cận bằng máy bay nhỏ hoặc tàu biển. Tại nhiều nơi, thiên nhiên vẫn quyết định nhịp sống của con người.&quot;],[0,&quot;Đó cũng là lý do người Mỹ gọi Alaska là \&quot;The Last Frontier\&quot; – Miền Biên Cương Cuối Cùng.&quot;]]],&quot;keyInsight&quot;:[0,&quot;Đám đông thường chỉ nhìn thấy hiện tại bằng sự hoài nghi, nhưng những vĩ nhân luôn nhìn thấu giá trị vĩnh cửu của tương lai.&quot;],&quot;highlightText&quot;:[0,&quot;Sự điên rồ của ngày hôm qua lại trở thành tầm nhìn chiến lược vĩ đại của tương lai.&quot;]}],[0,{&quot;id&quot;:[0,&quot;cheapest-deal&quot;],&quot;order&quot;:[0,4],&quot;title&quot;:[0,&quot;Thương Vụ Rẻ Nhất Lịch Sử Nhân Loại?&quot;],&quot;subtitle&quot;:[0,&quot;The Greatest Deal&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Chỉ vài thập kỷ sau khi Alaska được mua lại, những cơn sốt vàng bắt đầu bùng nổ tại vùng Yukon và Alaska.&quot;],[0,&quot;Hàng chục nghìn người đổ về phương Bắc với giấc mơ đổi đời. Những thị trấn mới mọc lên giữa vùng đất hoang dã. Những tuyến đường vận chuyển được mở rộng. Dòng tiền bắt đầu chảy về Alaska.&quot;],[0,&quot;Ngày nay, du khách vẫn có thể cảm nhận phần nào bầu không khí của thời kỳ ấy. Các thị trấn lịch sử như Skagway vẫn lưu giữ nhiều công trình gỗ cổ, những con phố mang đậm dấu ấn thời kỳ khai phá và các bảo tàng kể lại câu chuyện về những đoàn người từng vượt hàng nghìn kilomet để tìm kiếm vận may nơi phương Bắc.&quot;],[0,&quot;Đối với những người yêu lịch sử, đây là một trong những khía cạnh hấp dẫn nhất của Alaska mà không phải điểm đến nào tại Mỹ cũng có được.&quot;],[0,&quot;Nhưng vàng chỉ là sự khởi đầu.&quot;],[0,&quot;Trong thế kỷ 20, người ta tiếp tục phát hiện những mỏ dầu và khí đốt khổng lồ. Đường ống xuyên Alaska được xây dựng. Ngành thủy sản phát triển mạnh mẽ. Alaska dần trở thành một trong những vùng lãnh thổ có giá trị chiến lược quan trọng nhất nước Mỹ.&quot;],[0,&quot;Trong thời kỳ Chiến tranh Lạnh, vị trí địa lý của Alaska càng trở nên đặc biệt. Nằm giữa Bắc Mỹ và châu Á, nơi đây trở thành một trong những tuyến phòng thủ quan trọng nhất của nước Mỹ tại khu vực Bắc Cực.&quot;],[0,&quot;Ngày nay, nguồn lực kinh tế từ Alaska cũng góp phần tạo nên hệ thống hạ tầng hiện đại giúp du khách khám phá vùng đất này dễ dàng hơn. Các sân bay, cảng biển và dịch vụ du lịch được phát triển mạnh, nhưng phần lớn thiên nhiên Alaska vẫn giữ được trạng thái hoang sơ hiếm có.&quot;],[0,&quot;Chỉ cần rời xa các thị trấn một quãng ngắn, du khách đã có thể bắt gặp những cảnh quan gần như không thay đổi trong hàng nghìn năm.&quot;]]],&quot;keyInsight&quot;:[0,&quot;Không phải vàng hay dầu mỏ, mà chính vị trí địa chiến lược và sự hoang sơ vô tận mới là kho báu thực sự thay đổi cục diện lịch sử nước Mỹ.&quot;]}],[0,{&quot;id&quot;:[0,&quot;why-visit&quot;],&quot;order&quot;:[0,5],&quot;title&quot;:[0,&quot;Vì Sao Câu Chuyện Này Vẫn Hấp Dẫn Du Khách Ngày Nay?&quot;],&quot;subtitle&quot;:[0,&quot;Beyond The Gold&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Ngày nay, khi nhìn lại lịch sử, nhiều nhà nghiên cứu xem việc mua Alaska là một trong những quyết định đầu tư thành công nhất từng được thực hiện.&quot;],[0,&quot;Nhưng điều khiến câu chuyện này hấp dẫn không chỉ nằm ở tiền bạc. Mà nằm ở khả năng nhìn thấy giá trị trước khi phần còn lại của thế giới nhận ra nó.&quot;],[0,&quot;Đối với những người yêu khám phá, Alaska là vùng đất của băng hà, gấu nâu, cá voi và những hành trình phiêu lưu đặc biệt. Đối với những người yêu lịch sử, Alaska là câu chuyện về sự thay đổi của các đế chế. Còn đối với những người làm kinh doanh, đây là một bài học thú vị về tầm nhìn dài hạn.&quot;],[0,&quot;Đôi khi những cơ hội lớn nhất không xuất hiện dưới hình hài của một viên kim cương lấp lánh. Chúng xuất hiện dưới lớp băng lạnh giá. Và chỉ những người đủ kiên nhẫn mới nhận ra giá trị thật của chúng.&quot;],[0,&quot;Ngày nay, giá trị lớn nhất của Alaska đối với du khách có lẽ không nằm ở vàng hay dầu mỏ. Mà nằm ở việc vùng đất này vẫn giữ được tinh thần của một miền biên cương thực sự.&quot;],[0,&quot;Khi đứng trước một dòng sông băng hàng nghìn năm tuổi, khi nhìn thấy cá voi lưng gù trồi lên giữa đại dương hay bắt gặp một con gấu nâu đang săn cá hồi bên bờ sông, người ta dễ dàng hiểu vì sao Alaska luôn nằm trong danh sách những điểm đến đáng mơ ước nhất thế giới.&quot;],[0,&quot;Có lẽ đó cũng là lý do mà hơn một thế kỷ sau, Alaska vẫn tiếp tục thu hút những người yêu khám phá từ khắp nơi trên thế giới. Không chỉ vì vẻ đẹp thiên nhiên hùng vĩ, mà còn bởi nơi đây mang trong mình một trong những câu chuyện đáng kinh ngạc nhất về tầm nhìn, sự can đảm và những quyết định đã làm thay đổi lịch sử.&quot;],[0,&quot;Và đối với nhiều du khách, hành trình đến Alaska không đơn thuần là một chuyến du lịch. Đó là cơ hội để bước vào một vùng đất nơi thiên nhiên, lịch sử và tinh thần khám phá vẫn hiện diện rõ nét hơn bất cứ nơi nào khác tại nước Mỹ.&quot;]]],&quot;highlightText&quot;:[0,&quot;Hành trình đến Alaska không đơn thuần là một chuyến du lịch. Đó là cơ hội bước vào vùng đất nơi thiên nhiên, lịch sử và tinh thần khám phá hiện diện rõ nét nhất.&quot;],&quot;keyInsight&quot;:[0,&quot;Cơ hội lớn nhất đôi khi xuất hiện dưới lớp băng lạnh giá.&quot;]}]]],&quot;partNumber&quot;:[0,2]}],&quot;data-astro-cid-ltmw3ydh&quot;:[0,true]}" ssr="" client="idle" opts="{&quot;name&quot;:&quot;App&quot;,&quot;value&quot;:true}" await-children=""><div class="min-h-screen bg-[#060B0A] text-[#E5ECE9] selection:bg-emerald-500 selection:text-[#060B0A] transition-all duration-300 antialiased overflow-x-hidden relative font-sans" style="background-image:none"><div class="absolute inset-0 opacity-30 pointer-events-none" style="background-image:url(''data:image/svg+xml,%3Csvg viewBox=&quot;0 0 200 200&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot;%3E%3Cfilter id=&quot;noise&quot;%3E%3CfeTurbulence type=&quot;fractalNoise&quot; baseFrequency=&quot;0.8&quot; numOctaves=&quot;3&quot; stitchTiles=&quot;stitch&quot;/%3E%3C/filter%3E%3Crect width=&quot;100%25&quot; height=&quot;100%25&quot; filter=&quot;url(%23noise)&quot; opacity=&quot;0.015&quot;/%3E%3C/svg%3E'')"></div><section class="relative w-full h-[620px] md:h-[750px] overflow-hidden flex items-center justify-center border-b border-white/5 bg-slate-950"><div class="absolute inset-0 bg-[#09151A]"><img src="https://media.fittour.vn/uploads/du-lich-alaska-usa-phan-2-thuong-vu-72-trieu-usd-thay-doi-lich-su-nuoc-my.webp" alt="Alaska Chugach Glacier Mountain Range Backdrop cinematic" fetchpriority="high" class="w-full h-full object-cover object-center filter contrast-[1.05] saturate-[0.8] brightness-[0.45]" referrerpolicy="no-referrer"><div class="absolute inset-0 bg-emerald-950/15 mix-blend-multiply"></div><div class="absolute inset-0 bg-gradient-to-t from-[#060B0A] via-transparent to-transparent pointer-events-none"></div><div class="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-slate-950 to-transparent"></div></div><div class="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40 mix-blend-screen overflow-hidden"><div class="absolute w-[800px] h-[350px] bg-emerald-400/10 rounded-full blur-[120px] -rotate-12 transform -translate-y-24 translate-x-12 animate-pulse"></div><div class="absolute w-[600px] h-[250px] bg-sky-400/10 rounded-full blur-[100px] rotate-12 transform translate-y-24 -translate-x-12"></div></div><div class="max-w-4xl mx-auto px-6 z-20 text-center space-y-8"><div class="space-y-3.5"><span class="font-mono text-[#A8D1DB] text-[12px] md:text-[10px] md:text-[11px] tracking-[0.55em] uppercase font-black block animate-pulse">★ SERIES BLOG TRUYỀN KÝ DÃ NGOẠI ★</span><div class="w-14 h-[1.5px] bg-[#A8D1DB]/50 mx-auto"></div></div><div class="space-y-4"><h1 class="font-prata text-5xl md:text-7xl lg:text-8xl text-white font-normal leading-[0.95] uppercase tracking-tighter drop-shadow-xl select-all">ALASKA</h1><span class="font-serif italic text-2xl md:text-3xl text-amber-300 block font-light tracking-wide">Vì Sao Nga Bán Alaska Cho Mỹ Chỉ Với 7,2 Triệu USD?</span><p class="font-sans text-[13px] md:text-[11px] md:text-[12px] tracking-[0.35em] text-cyan-200 uppercase block font-black border-y border-white/5 py-2.5 max-w-lg mx-auto mt-4">PHẦN II • THƯƠNG VỤ LỊCH SỬ</p></div><p class="font-serif text-[15px] md:text-[18px] text-stone-200 font-light leading-relaxed max-w-2xl mx-auto italic select-all mt-8 mb-4">"Có những quyết định mà chỉ nhiều thập kỷ sau người ta mới nhận ra tầm nhìn thực sự của nó. Câu chuyện Alaska là một ví dụ điển hình."</p><div class="pt-8 text-stone-400 space-y-1 select-none animate-bounce"><span class="font-mono text-[10px] md:text-[8px] uppercase tracking-widest block">Kéo xuống để bắt đầu đọc sách</span></div></div></section><section class="max-w-4xl mx-auto px-6 pt-12 pb-6 flex flex-col items-center justify-center space-y-4"><span class="font-mono text-[#A8D1DB] text-[12px] md:text-[10px] tracking-[0.45em] uppercase font-black block">★ THỂ HIỆN BÀI VIẾT (PRESENTATION LAYER) ★</span><div class="flex bg-slate-950/90 border border-white/10 p-1 rounded-2xl w-full max-w-md shadow-2xl relative z-40"><button class="flex-1 py-2.5 px-3 rounded-xl font-sans text-sm md:text-xs font-bold uppercase tracking-wider transition-all duration-300 flex items-center justify-center gap-2 cursor-pointer text-stone-400 hover:text-white"><span>Tạp Chí Địa Lý</span></button><button class="flex-1 py-2.5 px-3 rounded-xl font-sans text-sm md:text-xs font-bold uppercase tracking-wider transition-all duration-300 flex items-center justify-center gap-2 cursor-pointer bg-[#915422] text-amber-100 shadow-md border border-amber-400/20"><span>Sổ Tay Viễn Chinh</span></button></div><p class="font-serif italic text-sm md:text-xs text-stone-400 text-center max-w-lg leading-relaxed">Đậm đặc phong vị Alaska: Trang sách gáy xoắn mộc bọc sương đọng, tọa độ thời tiết thực địa &amp; sớ triện đỏ dán tên lữ hành.</p></section><div class="max-w-4xl mx-auto px-6 py-6"><div class="bg-[#121B1C]/60 border border-white/5 hover:border-white/10 rounded-2xl p-6 md:p-8 relative flex flex-col md:flex-row items-center gap-8 transition-colors duration-500"><div class="shrink-0 relative w-28 h-28 md:w-40 md:h-40 rounded-full overflow-hidden border-[3px] border-[#121B1C] ring-2 ring-amber-500/20 shadow-xl"><img src="https://media.fittour.vn/uploads/max-vu-founder-fit-tour.webp" alt="Max Vũ" class="w-full h-full object-cover"></div><div class="flex-1 text-center md:text-left space-y-4"><div class="flex flex-col md:flex-row md:items-end justify-between gap-4"><div><div class="flex items-center justify-center md:justify-start gap-2 mb-2 flex-wrap"><span class="font-mono text-amber-500 text-[10px] tracking-[0.2em] uppercase font-bold bg-amber-500/10 px-2 py-1 rounded">TÁC GIẢ BÀI VIẾT &amp; TRIP PLANNER</span><span class="font-mono text-stone-400 text-[10px] uppercase font-bold pl-1">CEO FIT TOUR</span><span class="font-mono text-cyan-500/80 text-[10px] italic border-l border-stone-700 pl-2">10 NĂM KINH NGHIỆM</span></div><h2 class="font-serif text-3xl text-white">Max Vũ</h2></div><a href="https://fittour.vn/max-vu" target="_blank" rel="noopener noreferrer" class="inline-block px-6 py-2.5 bg-stone-900 border border-stone-700 hover:border-amber-500 hover:bg-amber-500/10 text-stone-300 hover:text-white font-mono text-[10px] uppercase tracking-widest font-bold rounded-full transition-all duration-300 whitespace-nowrap">XEM HỒ SƠ CHUYÊN GIA</a></div><p class="font-serif text-stone-300 text-[14.5px] leading-relaxed max-w-3xl">Người trực tiếp chắp bút cho series 10 bài viết này và đảm nhiệm vai trò <strong class="text-amber-100 font-medium">Chuyên gia thiết kế hành trình (Trip Planner)</strong> cho tuyến tour Alaska. Bằng kinh nghiệm thực chiến dạn dày, Max Vũ khát vọng đưa du khách vượt ra khỏi ranh giới truyền thống để thực sự chạm đến bản nguyên vĩ đại của miền biên cương Bắc Cực.</p></div></div></div><section class="max-w-4xl mx-auto px-6 py-8 space-y-16 relative"><article id="intro" class="p-6 md:p-10 md:pl-20 md:pr-12 rounded-2xl transition-all duration-300 text-left relative overflow-hidden border-2 bg-[#070F0D] border-emerald-500/25 text-[#E5ECE9] shadow-lg" style="opacity:0;transform:translateY(15px)"><div class="absolute left-3 top-0 bottom-0 hidden md:flex flex-col justify-around py-5 pointer-events-none z-30 select-none"><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div></div><div class="absolute top-20 right-5 md:right-12 w-28 h-28 rounded-full border border-dashed flex flex-col items-center justify-center p-2 text-center select-none pointer-events-none opacity-40 uppercase font-mono tracking-tighter border-emerald-400/40 text-emerald-300 rotate-6 bg-emerald-950/10"><span class="text-[9px] md:text-[7px] font-black tracking-widest leading-none">FIT TOUR</span><div class="w-16 h-[0.5px] bg-current my-0.5"></div><span class="text-[10.5px] md:text-[8.5px] font-black leading-none">EXPEDITION</span><span class="text-[9px] md:text-[7px] font-bold font-sans text-amber-500 truncate max-w-[80px] my-0.5">Lữ Khách Cực Bắc</span><div class="w-16 h-[0.5px] bg-current my-0.5"></div><span class="text-[9px] md:text-[7px] font-bold tracking-widest leading-none">ARNATIC 26</span></div><div class="border p-4 rounded-xl font-mono text-[12.5px] md:text-[10.5px] mb-6 space-y-1.5 relative z-10 border-white/10 bg-white/[0.015] text-stone-300"><div class="flex items-center justify-between text-sm md:text-xs font-black border-b border-dashed pb-1.5 mb-1 text-amber-500"><span class="flex items-center gap-1">BẢN THÔNG ĐIỆP ĐỊA TRÌNH</span><span>ENTRY 0<!-- -->1</span></div><div class="grid grid-cols-2 gap-x-4 gap-y-1.5"><div>TỌA ĐỘ: <span class="font-sans font-extrabold text-sky-400 block sm:inline">61.2181° N, 149.9003° W</span></div><div>THỜI TIẾT: <span class="font-sans font-extrabold text-emerald-450 block sm:inline">❄️ Bão tuyết mây dày</span></div><div>ĐỘ CAO: <span class="font-sans font-extrabold text-stone-400 block sm:inline">31m (Thung lũng Anchorage)</span></div><div>SỨC GIÓ: <span class="font-sans font-extrabold text-cyan-450 block sm:inline">18 km/h NNW (Cực Bắc)</span></div></div></div><div class="mb-6 relative z-10"><span class="font-mono text-[10px] md:text-[8px] text-amber-500 uppercase tracking-[0.3em] font-black block mb-1">★ POLAR FLIGHT LOG: PART <!-- -->2<!-- -->, CHAP. <!-- -->1<!-- --> ★</span><h2 class="font-prata text-2xl md:text-3xl text-emerald-300 uppercase font-normal tracking-wide">Những Quyết Định Bị Xem Là Sai Lầm</h2><span class="font-serif italic text-sm md:text-xs text-stone-400 block mt-0.5">"<!-- -->A Historical Misjudgment<!-- -->" — Trích dã sử viễn chinh</span></div><div class="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start relative z-10"><div class="lg:col-span-8 space-y-4"><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all"><span class="float-left text-3xl font-mono border-2 border-dashed border-amber-500/30 text-amber-500 bg-amber-500/5 p-1.5 px-2.5 rounded-lg mr-2 font-bold leading-none select-none">†</span>Trong lịch sử thế giới, có những quyết định bị xem là sai lầm ngay từ ngày đầu tiên.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Có những thương vụ khiến báo chí chế giễu, công chúng phản đối và giới quan sát không nhìn thấy bất kỳ giá trị nào phía trước.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Nhưng cũng có những quyết định mà chỉ nhiều thập kỷ sau người ta mới nhận ra tầm nhìn thực sự của nó.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Câu chuyện Alaska là một ví dụ điển hình.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Ngày nay, khi nhắc đến Alaska, người ta nghĩ đến những dãy núi phủ tuyết trắng, những dòng sông băng xanh thẳm, những đàn cá voi di cư mỗi mùa hè và nguồn tài nguyên thiên nhiên khổng lồ. Thế nhưng cách đây hơn 150 năm, vùng đất rộng hơn 1,7 triệu km² này từng được bán với giá chỉ 7,2 triệu USD.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Một con số khiến rất nhiều người ngày nay phải ngạc nhiên.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Liệu đây có phải là một trong những thương vụ rẻ nhất trong lịch sử nhân loại?</p><div class="p-4 rounded-xl border-y border-dashed relative my-5 bg-white/[0.015] border-white/5 text-amber-100"><span class="font-mono text-[9px] md:text-[7px] text-stone-450 uppercase tracking-widest block mb-1.5">✍️ BÚT TÍCH NGHIÊN CỨU:</span><p class="font-serif text-[15.5px] md:text-[13.5px] italic leading-relaxed text-left">"<!-- -->Một vùng đất trị giá hàng nghìn tỷ đô ngày nay từng được bán với giá chỉ 7,2 triệu USD.<!-- -->"</p></div></div><div class="lg:col-span-4 space-y-4"><div class="bg-red-950/25 border border-red-500/20 rounded-2xl p-4 text-left space-y-2 relative overflow-hidden"><div class="absolute top-0 right-0 w-12 h-12 bg-red-500/5 rounded-full blur-xl pointer-events-none"></div><div class="flex items-center gap-1.5 text-red-400 font-mono text-[10px] md:text-[8px] font-black uppercase tracking-widest"><span>KHUYẾN CÁO SINH TỒN THỰC ĐỊA</span></div><p class="font-serif text-sm md:text-xs md:text-xxs text-stone-300 leading-relaxed">Trang bị Áo Khoác Nam Cực Chống Bão Cát Tuyết (Parka) là bắt buộc tối thượng để phòng tử lạnh dưới -10°C.</p><div class="pt-2 border-t border-white/5 flex justify-between items-center text-[9.5px] md:text-[7.5px] font-mono text-red-400"><span>SỔ TẠY HUẤN LUYỆN</span><span class="cursor-pointer underline">Mở hòm vật tư ↳</span></div></div><div class="bg-amber-50 border border-amber-900/10 rounded-xl p-4 rotate-1 shadow-md text-stone-900 space-y-2"><span class="font-mono text-[9px] md:text-[7px] text-amber-900/90 uppercase tracking-widest block font-bold border-b border-amber-900/10 pb-1">📋 MEMOIR NOTE:</span><p class="font-sans text-[13px] md:text-[11px] font-medium leading-relaxed text-justify italic text-stone-850">"<!-- -->Có những quyết định mang tính lịch sử mà phải qua hàng trăm năm con người mới thực sự thấu hiểu tầm nhìn vĩ đại đằng sau nó.<!-- -->"</p><span class="font-mono text-[9.5px] md:text-[7.5px] text-stone-500 block text-right">— Signed, Curator Max Vu</span></div></div></div><div class="flex justify-between items-center border-t border-white/5 pt-4.5 mt-6 relative z-10 select-none"><span class="font-mono text-[10px] md:text-[8px] text-stone-505 tracking-wider hidden sm:block">EST. JUNE 12, 2026 • ARNATIC LOGS BY FIT TOUR</span></div><div class="flex gap-4 justify-center py-2 text-stone-700/10 select-none pointer-events-none mt-4"></div></article><article id="russian-alaska" class="p-6 md:p-10 md:pl-20 md:pr-12 rounded-2xl transition-all duration-300 text-left relative overflow-hidden border-2 bg-[#070F0D] border-emerald-500/25 text-[#E5ECE9] shadow-lg" style="opacity:0;transform:translateY(15px)"><div class="absolute left-3 top-0 bottom-0 hidden md:flex flex-col justify-around py-5 pointer-events-none z-30 select-none"><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div c